class IrisExactEvaluator:
    def __call__(self, *, response, ground_truth, **kwargs):
        labels = ("Iris-setosa", "Iris-versicolor", "Iris-virginica")
        valid = isinstance(response, str) and response.strip() in labels
        return {"classification_correctness": float(valid and response.strip() == ground_truth)}
